/* ===== src/tokens.css ===== */
/*
 * 苔雨溪笺 | Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */
@font-face {
    font-family: "Source Han Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Cormorant SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --ty-paper: #f0ede3;
    --ty-paper-deep: #e8e1d2;
    --ty-paper-soft: #f8f5ec;
    --ty-porcelain: #fbf8ee;
    --ty-leaf-wash: #e4eadb;
    --ty-leaf-soft: #cdd9c8;
    --ty-leaf: #748f79;
    --ty-petal-soft: #edd9d6;
    --ty-honey-soft: #efe2be;
    --ty-ink: #272c28;
    --ty-ink-soft: #4f5851;
    --ty-muted: #7e857d;
    --ty-muted-strong: #6f786e;
    --ty-moss: #536b5a;
    --ty-moss-deep: #29463a;
    --ty-moss-light: #aab5a6;
    --ty-oxblood: #70343a;
    --ty-gold: #9a8056;
    --ty-line: rgba(42, 58, 49, 0.13);
    --ty-line-strong: rgba(42, 58, 49, 0.24);
    --ty-info: #506f7a;
    --ty-success: #4d7259;
    --ty-warning: #9a6c3e;
    --ty-error: #8a4046;
    --ty-surface: rgba(246, 244, 238, 0.965);
    --ty-surface-strong: rgba(238, 236, 228, 0.985);
    --ty-shadow: 0 14px 42px rgba(35, 48, 40, 0.14);
    --ty-shadow-soft: 0 8px 24px rgba(35, 48, 40, 0.09);
    --ty-control-shadow: 0 5px 14px rgba(44, 65, 52, 0.11), inset 0 1px rgba(255,255,255,.55);
    --ty-control-shadow-hover: 0 7px 18px rgba(67, 75, 50, 0.16), inset 0 1px rgba(255,255,255,.62);
    --ty-radius-s: 3px;
    --ty-radius-m: 7px;
    --ty-radius-l: 12px;
    --ty-gap-1: 0.35rem;
    --ty-gap-2: 0.65rem;
    --ty-gap-3: 1rem;
    --ty-gap-4: 1.5rem;
    --ty-speed: 180ms;
    --ty-body: "Source Han Serif SC", "Noto Serif SC", "Songti SC", SimSun, serif;
    --ty-display: "Cormorant SC", "Source Han Serif SC", serif;
    --ty-side-bg: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/0a4003b88098fa0d8f5a22f9e509cea7a3c3eb8e/assets/%E8%8B%94%E9%9B%A8%E6%BA%AA%E7%AC%BA/moon-pavilion-sides-v8.png");
    --topBarBlockSize: 56px;
    --bottomFormBlockSize: 44px;
}

body {
    --SmartThemeBodyColor: var(--ty-ink);
    --SmartThemeEmColor: var(--ty-oxblood);
    --SmartThemeQuoteColor: var(--ty-oxblood);
    --SmartThemeBlurTintColor: var(--ty-surface-strong);
    --SmartThemeChatTintColor: rgba(238, 236, 228, 0.86);
    --SmartThemeBorderColor: var(--ty-line);
    --SmartThemeShadowColor: transparent;
    --shadowWidth: 0;
    color: var(--ty-ink);
    background: var(--ty-paper-deep);
    font-family: var(--ty-body);
    text-shadow: none;
}

body :is(input, textarea, select, button, .menu_button):not(.fa):not(.fa-solid):not(.fa-regular):not(.fa-brands) {
    font-family: var(--ty-body);
}

body :is(.fa, .fa-solid, .fa-regular, .fa-brands) {
    font-family: var(--FA-family-classic, "Font Awesome 6 Free");
}

body ::selection {
    color: var(--ty-paper-soft);
    background: var(--ty-moss-deep);
}

body :focus-visible {
    outline: 2px solid var(--ty-oxblood);
    outline-offset: 2px;
    filter: none;
}

@media (prefers-reduced-motion: reduce) {
    body :is(#sheld,#chat,#top-bar,#top-settings-holder,#send_form,.mes,.mes_buttons,.drawer-toggle,.drawer-content,.popup,.toast,.menu_button,input,textarea,select,button),
    body :is(#sheld,#chat,#top-bar,#send_form,.mes,.drawer-toggle,.menu_button)::before,
    body :is(#sheld,#chat,#top-bar,#send_form,.mes,.drawer-toggle,.menu_button)::after {
        scroll-behavior: auto;
        transition-duration: 0.01ms;
        animation-duration: 0.01ms;
        animation-iteration-count: 1;
    }
}

/* ===== src/chat-layout.css ===== */
/* L05 无直线纸纹编辑页 + 官方可替换外侧月亭山水；结构合同：taiyu-editorial-v10 */
#bg1 {
    background-color: var(--ty-moss-deep);
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
    filter: saturate(.9) contrast(.96) brightness(.98);
}

/* 酒馆1.14把“未选择背景”写成透明占位URL；仅在无样式或该占位URL时提供主题默认图。 */
#bg1:not([style]),
#bg1[style*="__transparent.png"] {
    background-image: var(--ty-side-bg) !important;
}

#sheld {
    background: var(--ty-paper);
    isolation: isolate;
    box-shadow: 0 0 0 1px rgba(42,58,49,.16), 0 0 34px rgba(24,35,29,.18);
}

#chat {
    position: relative;
    z-index: 1;
    align-items: stretch;
    padding: clamp(1.15rem, 2.4vw, 2.75rem) clamp(1rem, 4.6vw, 4.75rem) 2.5rem;
    border: 0;
    background-color: rgba(238, 236, 228, 0.97);
    background-image:
        radial-gradient(ellipse at 16% 12%, rgba(205,217,200,.28), transparent 34%),
        radial-gradient(ellipse at 84% 38%, rgba(239,226,190,.22), transparent 31%),
        radial-gradient(ellipse at 45% 92%, rgba(237,217,214,.18), transparent 38%);
    background-size: 100% 100%;
    scrollbar-width: none;
    scrollbar-gutter: auto;
    text-shadow: none;
}

#chat::-webkit-scrollbar {
    width: 0;
    height: 0;
}

#chat::before {
    content: none;
    display: none;
}

#chat .mes {
    position: relative;
    width: 100%;
    max-width: 64rem;
    margin: 0 auto;
    padding: clamp(1rem, 2.2vw, 1.8rem) 0;
    border: 0;
    background: transparent;
    color: var(--ty-ink);
    text-shadow: none;
    box-shadow: none;
}

#chat .mes + .mes {
    border-top: 0;
}

#chat .mes[is_user="false"] .mesAvatarWrapper,
#chat .mes[is_system="true"] .mesAvatarWrapper {
    display: none;
    flex: 0 0 0;
    width: 0;
    margin: 0;
}

#chat .mes[is_user="true"] {
    align-items: flex-start;
    column-gap: clamp(0.65rem, 1.6vw, 1rem);
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
    position: relative;
    display: flex;
    flex: 0 0 clamp(44px, 4vw, 52px);
    width: clamp(44px, 4vw, 52px);
    margin: 0.05rem 0 0;
    align-items: flex-start;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    width: clamp(44px, 4vw, 52px);
    height: clamp(44px, 4vw, 52px);
    overflow: hidden;
    border: 1px solid var(--ty-moss);
    border-radius: 48% 48% 10% 48%;
    background: var(--ty-paper-deep);
    box-shadow: 4px 4px 0 rgba(154,128,86,.16);
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: saturate(.78) contrast(.96) sepia(.06);
}

#chat .mes[is_user="true"] .mesAvatarWrapper::after {
    content: "";
    position: absolute;
    right: -0.22rem;
    bottom: -0.18rem;
    width: 0.5rem;
    height: 0.5rem;
    border: 1px solid var(--ty-paper-soft);
    border-radius: 50%;
    background: var(--ty-oxblood);
    pointer-events: none;
}

#chat .mes_block {
    flex: 1 1 auto;
    min-width: 0;
    width: 100%;
    margin: 0;
    padding: 0;
    background: transparent;
}

#chat .mes .ch_name {
    min-height: 1.8rem;
    margin: 0 0 0.9rem;
    align-items: baseline;
    border: 0;
}

#chat .name_text {
    color: var(--ty-moss-deep);
    font-family: var(--ty-display);
    font-size: 0.88em;
    font-weight: 400;
    letter-spacing: 0.22em;
    text-transform: uppercase;
}

#chat .timestamp,
#chat :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay, .swipes-counter) {
    color: var(--ty-muted-strong);
    font-family: var(--ty-display);
    font-size: 0.78em;
    letter-spacing: 0.08em;
    opacity: 1;
    text-shadow: none;
}

#chat .timestamp { margin-inline-start: 0.8rem; }

#chat .mes_buttons,
#chat .mes_edit_buttons {
    color: var(--ty-moss-deep);
    opacity: 1 !important;
    filter: none !important;
    text-shadow: none !important;
    box-shadow: none !important;
    transition: color var(--ty-speed), transform var(--ty-speed);
}

#chat :is(.mes_buttons, .mes_edit_buttons) :is(.mes_button, .menu_button, .fa, .fa-solid, .fa-regular, .fa-ellipsis, .fa-pencil, .fa-pen) {
    color: var(--ty-moss-deep) !important;
    background-color: transparent !important;
    opacity: 1 !important;
    filter: none !important;
    text-shadow: none !important;
    box-shadow: none !important;
}

#chat .mes_button:hover,
#chat .mes_button:focus-visible,
#chat .menu_button:hover,
#chat .menu_button:focus-visible {
    color: var(--ty-oxblood) !important;
    opacity: 1 !important;
    filter: none !important;
    text-shadow: none !important;
    box-shadow: none !important;
}

#chat .mes[is_user="true"] {
    max-width: 48rem;
    margin-inline-end: 0;
    padding-block: 1.05rem 1.4rem;
}

#chat .mes[is_user="true"] .mes_block {
    padding: clamp(.8rem, 2vw, 1.25rem) clamp(1rem, 3vw, 2.2rem);
    border: 0;
    border-radius: 20px 7px 20px 7px;
    background: linear-gradient(135deg, rgba(237,217,214,.42), rgba(248,245,236,.58));
    box-shadow: 0 8px 24px rgba(63,46,48,.08);
}

#chat .mes[is_user="true"] .ch_name {
    flex-direction: row-reverse;
}

#chat .mes[is_user="true"] .name_text { color: var(--ty-oxblood); }

#chat .mes[is_user="false"][is_system="false"] .mes_block {
    max-width: 58rem;
    margin-inline: auto;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::before {
    content: "❧";
    width: auto;
    height: auto;
    margin-inline-end: 0.55rem;
    color: var(--ty-leaf);
    background: transparent;
    font-family: var(--ty-body);
    font-size: 1rem;
}

#chat .mes[is_system="true"] {
    max-width: 46rem;
    margin-block: 0.6rem;
    padding: 0.8rem 1rem;
    border: 0;
    border-radius: 16px 5px 16px 5px;
    background: rgba(228,234,219,.62);
    color: var(--ty-ink-soft);
    box-shadow: var(--ty-control-shadow);
}

#chat :is(.swipe_left, .swipe_right, .swipeRightBlock) {
    color: var(--ty-moss);
    filter: none;
    text-shadow: none;
}

#chat .mes_media_wrapper,
#chat .mes_file_wrapper {
    max-width: 100%;
    border-color: var(--ty-line);
}

@media (max-width: 1000px) {
    #chat { padding-inline: clamp(0.9rem, 3.5vw, 2.2rem); }
}

@media (max-width: 600px) {
    #chat {
        padding: 1rem 0.9rem 2rem;
        background-color: rgba(238,236,228,.985);
    }
    #chat .mes,
    #chat .mes[is_user="true"] {
        max-width: 100%;
        margin-inline: auto;
        padding-block: 0.9rem 1.15rem;
    }
    #chat .mes[is_system="false"] {
        flex-direction: column;
        align-items: stretch;
        column-gap: 0;
    }
    #chat .mes[is_system="false"] > .mesAvatarWrapper {
        align-self: center;
        margin-inline: auto;
    }
    #chat .mes[is_system="false"] > .mes_block {
        inline-size: 100%;
        min-inline-size: 0;
        margin-inline: auto;
    }
    #chat .mes[is_system="false"] > .mes_block > .mes_text {
        inline-size: min(100%, 34rem);
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: .4rem !important;
        box-sizing: border-box;
    }
    #chat .mes[is_user="true"] .mesAvatarWrapper,
    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
        flex-basis: 40px;
        width: 40px;
        height: 40px;
    }
    #chat .mes[is_user="true"] .mes_block {
        margin-top: .55rem;
        padding: .95rem .65rem;
    }
    #chat .ch_name { gap: 0.35rem; }
    #chat .name_text { letter-spacing: 0.14em; }
}

/* ===== src/full-text.css ===== */
/* T02 杂志编辑；只处理正文语义，不补偿父级几何。 */
#chat .mes_text {
    color: var(--ty-ink);
    font-family: var(--ty-body);
    font-size: 0.98em;
    font-weight: 400;
    line-height: 1.92;
    letter-spacing: 0.035em;
    overflow-wrap: anywhere;
    text-wrap: pretty;
}

#chat .mes[is_user="true"] .mes_text {
    color: var(--ty-ink-soft);
    font-size: 1.02em;
    line-height: 1.75;
}

#chat .mes_text p { margin: 0 0 1.05em; }
#chat .mes_text p:last-child { margin-bottom: 0; }

#chat .mes_text :is(h1,h2,h3,h4,h5,h6) {
    margin: 1.45em 0 0.65em;
    color: var(--ty-moss-deep);
    font-family: var(--ty-display);
    font-weight: 400;
    line-height: 1.28;
    letter-spacing: 0.08em;
}

#chat .mes_text h1 { font-size: 1.8em; }
#chat .mes_text h2 { font-size: 1.48em; }
#chat .mes_text h3 { font-size: 1.24em; }

#chat .mes_text :is(strong,b) {
    color: var(--ty-oxblood);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#chat .mes_text :is(em,i) { color: var(--ty-moss-deep); }

#chat .mes_text blockquote {
    margin: 1.35em 0;
    padding: .85em 1em;
    border-inline-start: 0;
    border-radius: 18px 6px 18px 6px;
    background: linear-gradient(135deg, rgba(237,217,214,.42), rgba(251,248,238,.72));
    color: #5b3c3e;
    font-style: normal;
    box-shadow: 0 6px 18px rgba(63,46,48,.07);
}

#chat .mes_text hr {
    width: min(62%, 24rem);
    height: 1px;
    margin: 2em auto;
    border: 0;
    background: linear-gradient(90deg, transparent, var(--ty-line-strong), transparent);
}

#chat .mes_text :is(ul,ol) { padding-inline-start: 1.5em; }
#chat .mes_text li { margin-block: 0.35em; }

#chat .mes_text a {
    color: var(--ty-moss-deep);
    text-decoration-color: var(--ty-gold);
    text-underline-offset: 0.18em;
}

#chat .mes_text :not(pre) > code {
    padding: 0.08em 0.38em;
    border: 1px solid var(--ty-line);
    border-radius: var(--ty-radius-s);
    background: rgba(83,107,90,.08);
    color: var(--ty-oxblood);
    font-family: ui-monospace, "Cascadia Mono", Consolas, monospace;
    font-size: 0.9em;
}

#chat .mes_text pre {
    max-width: 100%;
    margin: 1.2em 0;
    padding: 1em;
    overflow-x: auto;
    border: 1px solid var(--ty-line);
    border-radius: var(--ty-radius-m);
    background: #29342e;
    color: #edf0e8;
    text-shadow: none;
}

#chat .mes_text pre code { color: inherit; font-family: ui-monospace, "Cascadia Mono", Consolas, monospace; }

#chat .mes_text table {
    display: block;
    max-width: 100%;
    margin: 1.3em 0;
    overflow-x: auto;
    border-collapse: collapse;
}

#chat .mes_text :is(th,td) {
    padding: 0.55em 0.75em;
    border: 1px solid var(--ty-line);
    background: rgba(246,244,238,.68);
}

#chat .mes_text th { color: var(--ty-moss-deep); font-weight: 400; letter-spacing: 0.06em; }
#chat .mes_text img { max-width: 100%; height: auto; border-radius: var(--ty-radius-m); box-shadow: var(--ty-shadow-soft); }

#chat .mes_reasoning_details {
    margin: 0.85rem 0 1.1rem;
    border: 0;
    border-radius: 18px 6px 18px 6px;
    background: linear-gradient(135deg, rgba(228,234,219,.72), rgba(251,248,238,.8));
    color: var(--ty-ink-soft);
    box-shadow: var(--ty-control-shadow);
}

#chat .mes_reasoning_details .mes_reasoning_summary {
    margin: 0;
    padding: 0;
    color: var(--ty-moss-deep);
    background: transparent;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_header {
    min-height: 2.7rem;
    margin: 0;
    padding: 0.68rem 2.2rem 0.68rem 1rem;
    border: 0;
    border-inline-start: 0;
    border-radius: 18px 6px 0 0;
    color: var(--ty-moss-deep);
    background: linear-gradient(90deg, rgba(83,107,90,.14), rgba(246,244,238,.76)) !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
}

#chat .mes_reasoning_details .mes_reasoning_header:is(:hover,:focus-visible) {
    color: var(--ty-oxblood);
    background: linear-gradient(90deg, rgba(112,52,58,.12), rgba(246,244,238,.82)) !important;
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
    color: var(--ty-gold);
    filter: none;
    text-shadow: none;
}

#chat .mes_reasoning_header_title { font-size: 0; }
#chat .mes_reasoning_header_title::after {
    content: "听雨片刻";
    font-size: 0.88rem;
    letter-spacing: 0.12em;
}

#chat .mes_reasoning,
#chat .mes_reasoning_details[open] .mes_reasoning {
    padding: 0.8rem 1rem 1rem;
    border-top: 0;
    border-inline-start: 0;
    border-radius: 0;
    color: var(--ty-ink-soft);
    background: rgba(246,244,238,.55);
    box-shadow: none;
    filter: none;
    text-shadow: none;
}

#chat .mes_reasoning_details :is(.fa-solid,.menu_button,.mes_button) {
    color: var(--ty-moss);
    opacity: 0.82;
    filter: none;
}

@media (max-width: 600px) {
    #chat .mes_text { font-size: 0.97em; line-height: 1.82; letter-spacing: 0.02em; }
    #chat .mes_text blockquote { margin-inline: 0; padding-inline-start: 0.85em; }
}

/* ===== src/windows/topbar.css ===== */
/* 顶栏使用真实.drawer-icon生成链；不再用.drawer-toggle伪元素覆盖原图标。 */
#top-bar {
    height: var(--topBarBlockSize);
    border: 0;
    background:
        radial-gradient(ellipse at 14% 0, rgba(205,217,200,.34), transparent 27%),
        radial-gradient(ellipse at 78% 100%, rgba(237,217,214,.25), transparent 32%),
        rgba(240,237,227,.97);
    box-shadow: 0 7px 22px rgba(39,53,45,.08), inset 0 -5px 12px rgba(154,128,86,.07);
}

:is(#ai-config-button,#sys-settings-button,#advanced-formatting-button,#WI-SP-button,#user-settings-button,#backgrounds-button,#extensions-settings-button,#persona-management-button,#rightNavHolder) > .drawer-toggle {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 100%;
    height: var(--topBarBlockSize);
    min-width: 44px;
    min-height: var(--topBarBlockSize);
    padding: 0;
    color: var(--ty-moss-deep);
    border: 0;
    background: transparent;
    opacity: 1;
    filter: none !important;
    text-shadow: none;
    pointer-events: auto !important;
    cursor: pointer;
    touch-action: manipulation;
    user-select: none;
    transition: color var(--ty-speed), background-color var(--ty-speed);
}

/* 关闭v6覆盖图层；新图案直接在真实.drawer-icon::before上生成。 */
:is(#ai-config-button,#sys-settings-button,#advanced-formatting-button,#WI-SP-button,#user-settings-button,#backgrounds-button,#extensions-settings-button,#persona-management-button,#rightNavHolder) > .drawer-toggle::after {
    content: none;
    display: none;
    background-image: none;
}

:is(#ai-config-button,#sys-settings-button,#advanced-formatting-button,#WI-SP-button,#user-settings-button,#backgrounds-button,#extensions-settings-button,#persona-management-button,#rightNavHolder) > .drawer-toggle > .drawer-icon {
    position: relative;
    inset: auto;
    display: inline-grid;
    place-content: center;
    box-sizing: border-box;
    width: 2.2rem;
    height: 2.2rem;
    padding: 0;
    color: var(--ty-moss-deep);
    border: 0;
    border-radius: 72% 28% 68% 32%;
    background: linear-gradient(145deg, var(--ty-porcelain), var(--ty-leaf-wash));
    font-size: 1.05rem;
    line-height: 1;
    opacity: 1;
    filter: none !important;
    text-shadow: none !important;
    box-shadow: var(--ty-control-shadow) !important;
    pointer-events: none;
