/* ===== src/windows/input.css ===== */
#form_sheld {
    position: relative;
    z-index: 2;
    background: transparent;
}

#send_form {
    min-height: 56px;
    border: 0;
    border-top: 0;
    border-radius: 0;
    background: rgba(238,236,228,.985);
    box-shadow: 0 -8px 24px rgba(39,53,45,.07);
}

#send_form #nonQRFormItems {
    min-height: 56px;
    align-items: center;
    gap: 0.25rem;
    font-size: 1rem;
}

#send_textarea {
    min-height: 44px;
    max-height: 32vh;
    padding: 0.75rem 0.7rem;
    border: 0;
    border-inline: 0;
