#send_textarea::placeholder { color: var(--ty-muted-strong); opacity: .9; }
#send_textarea:focus { background: var(--ty-porcelain); box-shadow: 0 0 0 2px rgba(116,143,121,.2); }

#leftSendForm,
#rightSendForm {
    flex: 0 0 auto;
    flex-wrap: nowrap;
    align-items: center;
}

#leftSendForm > div,
#rightSendForm > div:not(.mes_stop),
#send_form .mes_stop {
    width: 40px;
    min-width: 40px;
    height: 40px;
    color: var(--ty-moss-deep);
    border: 0;
    border-radius: 72% 28% 68% 32%;
    background: linear-gradient(145deg, var(--ty-porcelain), var(--ty-leaf-wash));
    opacity: 1;
    filter: none;
    text-shadow: none;
    box-shadow: var(--ty-control-shadow);
    transition: color var(--ty-speed), border-color var(--ty-speed), background-color var(--ty-speed), transform var(--ty-speed);
