#leftSendForm > div:is(:hover,:focus-visible),
#rightSendForm > div:is(:hover,:focus-visible),
#send_form .mes_stop:is(:hover,:focus-visible) {
    color: var(--ty-oxblood);
    border-color: transparent;
    background: linear-gradient(145deg, var(--ty-porcelain), var(--ty-petal-soft));
    opacity: 1;
    filter: none;
    transform: translateY(-1px);
}

#send_but {
    color: var(--ty-paper-soft) !important;
    border-color: transparent !important;
    background: linear-gradient(145deg, #87464c, var(--ty-oxblood)) !important;
    box-shadow: inset 0 0 0 1px rgba(246,244,238,.22), 0 2px 0 rgba(64,27,31,.22) !important;
}

#mes_stop {
    color: var(--ty-paper-soft) !important;
    border-color: transparent !important;
    background: linear-gradient(145deg, #9b555b, var(--ty-error)) !important;
}

#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
    min-height: 34px;
    border: 0;
    border-inline-start: 0;
    border-radius: 16px 5px 16px 5px;
    color: var(--ty-moss-deep);
    background: linear-gradient(90deg, rgba(228,225,215,.94), rgba(246,244,238,.92));
    box-shadow: var(--ty-control-shadow);
    filter: none;
    text-shadow: none;
}

#qr--bar > .qr--buttons .qr--button:is(:hover,:focus-visible),
#qr--popout > .qr--body > .qr--buttons .qr--button:is(:hover,:focus-visible) {
