}
#send_form.no-connection { border-top-color: color-mix(in srgb, var(--ty-warning) 58%, transparent); }
body[data-generating="true"] #send_form { border-top-color: var(--ty-oxblood); }
body[data-generating="true"] #mes_stop { color: var(--ty-error); }

#send_form :is(.file_attached, #file_form) {
