/* ===== src/windows/controls.css ===== */
/* 通用控件采用雨后草木纸笺语言；几何仍由各窗口自身规则负责。 */
body :is(.drawer-content,.popup,.popup-content) :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]),textarea,select,.text_pole) {
    color: var(--ty-ink);
    border: 0;
    border-radius: 12px 4px 12px 4px;
    background: var(--ty-porcelain);
    box-shadow: inset 0 0 0 1px rgba(116,143,121,.12), 0 3px 10px rgba(44,65,52,.06);
    text-shadow: none;
}

body :is(.drawer-content,.popup,.popup-content) :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]),textarea,select,.text_pole):focus {
    border-color: transparent;
    background: #fffdf5;
    box-shadow: 0 0 0 2px rgba(116,143,121,.24), 0 4px 14px rgba(44,65,52,.08);
}

body :is(.drawer-content,.popup,.popup-content) :is(input,textarea,select,.text_pole):disabled {
    color: var(--ty-ink-soft);
    border-color: transparent;
    background: rgba(239,226,190,.58);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

body :is(.drawer-content,.popup,.popup-content) :is(select,option,optgroup) {
    color: var(--ty-ink);
    background-color: var(--ty-leaf-wash);
}

body :is(.drawer-content,.popup,.popup-content) option:checked {
    color: var(--ty-paper-soft);
    background-color: var(--ty-moss-deep);
}

/* 数值滑杆：加厚渐变枝条轨道，叶片拇指；不影响滚动条策略。 */
body input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    height: 1.35rem;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: transparent;
    background-size: auto;
    box-shadow: none;
    filter: none;
}

body input[type="range"]::-webkit-slider-runnable-track {
    height: .48rem;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(90deg, var(--ty-leaf), var(--ty-honey-soft));
    box-shadow: inset 0 1px 2px rgba(41,70,58,.2), 0 2px 7px rgba(44,65,52,.08);
}

body input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 1.05rem;
    height: 1.35rem;
    margin-top: -.43rem;
    border: 0;
    border-radius: 78% 22% 72% 28%;
    background: linear-gradient(145deg, var(--ty-petal-soft), var(--ty-oxblood));
    box-shadow: 0 3px 9px rgba(68,35,39,.24), inset 0 0 0 2px rgba(255,255,255,.48);
    transform: rotate(28deg);
}

body input[type="range"]::-moz-range-track {
    height: .48rem;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(90deg, var(--ty-leaf), var(--ty-honey-soft));
    box-shadow: inset 0 1px 2px rgba(41,70,58,.2), 0 2px 7px rgba(44,65,52,.08);
}

body input[type="range"]::-moz-range-thumb {
    width: 1.05rem;
    height: 1.35rem;
    border: 0;
    border-radius: 78% 22% 72% 28%;
    background: linear-gradient(145deg, var(--ty-petal-soft), var(--ty-oxblood));
    box-shadow: 0 3px 9px rgba(68,35,39,.24), inset 0 0 0 2px rgba(255,255,255,.48);
    transform: rotate(28deg);
}

body input[type="range"]:is(:hover,:focus-visible) {
    outline: 2px solid rgba(116,143,121,.3);
    outline-offset: 2px;
    filter: none;
}

/* 复选框完整重建官方::before生成链：选中后显示一枚浅色叶片。 */
body :is(input[type="checkbox"],input[type="radio"]) {
    -webkit-appearance: none;
    appearance: none;
    position: relative;
    display: inline-grid;
    place-content: center;
    box-sizing: border-box;
    width: 1.16em;
    height: 1.16em;
    flex: 0 0 1.16em;
    overflow: visible;
    border: 0;
    outline: 0;
    background: linear-gradient(145deg, var(--ty-porcelain), var(--ty-leaf-wash));
    box-shadow: inset 0 0 0 1px rgba(83,107,90,.18), 0 2px 6px rgba(44,65,52,.1);
    filter: none;
    opacity: 1;
    cursor: pointer;
}

body input[type="checkbox"] {
    color: var(--ty-ink);
    border-radius: 78% 22% 72% 28%;
    background-color: transparent;
}

body input[type="checkbox"]::before {
    content: "";
    width: .48em;
    height: .72em;
    border-radius: 100% 0 100% 0;
    background: var(--ty-paper-soft);
    clip-path: none;
    box-shadow: none !important;
    transform: scale(0) rotate(-20deg);
    transform-origin: center;
    transition: transform var(--ty-speed) ease;
}

body input[type="checkbox"]:checked {
    border-color: transparent;
    background: linear-gradient(145deg, var(--ty-leaf), var(--ty-moss-deep));
    box-shadow: 0 3px 9px rgba(41,70,58,.2), inset 0 0 0 1px rgba(255,255,255,.28);
    filter: none !important;
}

body input[type="checkbox"]:checked::before {
    transform: scale(1) rotate(-20deg);
}

body input[type="radio"] { border-radius: 50%; }
body input[type="radio"]::before {
    content: "✦";
    color: var(--ty-paper-soft);
    font-family: var(--ty-body);
    font-size: .72em;
    line-height: 1;
    transform: scale(0) rotate(-18deg);
    transition: transform var(--ty-speed) ease;
}
body input[type="radio"]:checked {
    background: linear-gradient(145deg, var(--ty-gold), var(--ty-oxblood));
}
body input[type="radio"]:checked::before { transform: scale(1) rotate(0); }

body :is(input[type="checkbox"],input[type="radio"]):focus-visible {
    outline: 2px solid var(--ty-gold);
    outline-offset: 2px;
}

body :is(input[type="checkbox"],input[type="radio"]):disabled {
    color: var(--ty-ink-soft);
    background: rgba(239,226,190,.58);
    box-shadow: inset 0 0 0 1px rgba(154,128,86,.16);
    filter: none !important;
    opacity: 1;
    cursor: not-allowed;
}

body input[type="checkbox"]:disabled:checked {
    background: linear-gradient(145deg, var(--ty-gold), var(--ty-muted-strong));
}

/* 通用按钮：取消官方灰阶与细框，改为叶片/花瓣纸钮。 */
body :is(.drawer-content,.popup,.popup-content) :is(.menu_button,.right_menu_button) {
    color: var(--ty-moss-deep);
    border: 0;
    border-color: transparent;
    border-radius: 70% 30% 64% 36%;
    background: linear-gradient(145deg, var(--ty-porcelain), var(--ty-leaf-wash));
    box-shadow: var(--ty-control-shadow);
    text-shadow: none;
    filter: none;
    opacity: 1;
}

body :is(.drawer-content,.popup,.popup-content) :is(.menu_button,.right_menu_button):is(:hover,:focus-visible) {
    color: var(--ty-oxblood);
    border-color: transparent;
    background: linear-gradient(145deg, var(--ty-porcelain), var(--ty-petal-soft));
    box-shadow: var(--ty-control-shadow-hover);
    filter: none;
    opacity: 1;
}

body :is(.drawer-content,.popup,.popup-content) .menu_button:is(.active,.selected,.toggled,.toggleEnabled,[aria-pressed="true"]) {
    color: var(--ty-paper-soft) !important;
    background: linear-gradient(145deg, var(--ty-leaf), var(--ty-moss-deep));
    box-shadow: 0 4px 12px rgba(41,70,58,.2), inset 0 1px rgba(255,255,255,.22);
    filter: none !important;
    opacity: 1 !important;
}

body :is(.drawer-content,.popup,.popup-content) .menu_button:is([disabled],.disabled) {
    color: var(--ty-ink-soft);
    border-color: transparent;
    background: rgba(239,226,190,.62);
    opacity: 1;
    box-shadow: none;
    filter: none;
    text-shadow: none;
}

body :is(.drawer-content,.popup,.popup-content) .menu_button.toggleable.toggled::before {
    content: "\f06c";
    color: var(--ty-paper-soft);
    font-family: "Font Awesome 6 Free";
    font-weight: 900;
}

body :is(.drawer-content,.popup,.popup-content) .menu_button.toggleable:not(.toggled)::before {
    content: "\f111";
    color: var(--ty-oxblood);
    font-family: "Font Awesome 6 Free";
    font-weight: 900;
}

body :is(.drawer-content,.popup,.popup-content) :is(h2,h3,h4,h5,.standoutHeader) {
    color: var(--ty-moss-deep);
    font-family: var(--ty-display);
    font-weight: 400;
    letter-spacing: .04em;
    text-shadow: none;
}

body :is(.drawer-content,.popup,.popup-content) :is(.inline-drawer-header,.panelControlBar) {
    color: var(--ty-ink-soft);
    border: 0;
    border-radius: 16px 5px 16px 5px;
    background: linear-gradient(135deg, rgba(228,234,219,.88), rgba(251,248,238,.94));
    box-shadow: var(--ty-control-shadow);
    text-shadow: none;
    filter: none;
}

/* 折叠图标直接替换真实.inline-drawer-icon::before，叶片方向表达开合。 */
body :is(#left-nav-panel,#AdvancedFormatting,#WorldInfo,#user-settings-block,#rm_extensions_block,#PersonaManagement,#right-nav-panel,#completion_prompt_manager,#extensions_settings,#extensions_settings2) .inline-drawer-icon {
    display: inline-grid;
    place-content: center;
    width: 1.8rem;
    height: 1.8rem;
    flex: 0 0 1.8rem;
    color: var(--ty-paper-soft);
    border: 0;
    border-radius: 78% 22% 72% 28%;
    background: linear-gradient(145deg, var(--ty-leaf), var(--ty-moss-deep));
    box-shadow: 0 3px 9px rgba(41,70,58,.18);
    filter: none !important;
    text-shadow: none !important;
    transition: transform var(--ty-speed), background var(--ty-speed);
}

body :is(#left-nav-panel,#AdvancedFormatting,#WorldInfo,#user-settings-block,#rm_extensions_block,#PersonaManagement,#right-nav-panel,#completion_prompt_manager,#extensions_settings,#extensions_settings2) .inline-drawer-icon::before {
    content: "\f06c" !important;
    display: block;
    color: currentColor;
    font-family: "Font Awesome 6 Free";
    font-weight: 900;
    font-size: .82rem;
    line-height: 1;
}

body :is(#left-nav-panel,#AdvancedFormatting,#WorldInfo,#user-settings-block,#rm_extensions_block,#PersonaManagement,#right-nav-panel,#completion_prompt_manager,#extensions_settings,#extensions_settings2) .inline-drawer-icon:is(.down,.fa-circle-chevron-down) {
    transform: rotate(18deg);
