body :is(#left-nav-panel,#AdvancedFormatting,#WorldInfo,#user-settings-block,#rm_extensions_block,#PersonaManagement,#right-nav-panel,#completion_prompt_manager,#extensions_settings,#extensions_settings2) .inline-drawer-icon:is(.up,.fa-circle-chevron-up,.fa-circle-chevron-right) {
    transform: rotate(-58deg);
}

