/* ===== src/windows/popups.css ===== */
.popup,
.popup-content,
#dialogue_popup,
#completion_prompt_manager_popup {
    color: var(--ty-ink);
    border: 1px solid var(--ty-line-strong);
    border-radius: var(--ty-radius-l);
    background: var(--ty-surface-strong);
    box-shadow: var(--ty-shadow);
    text-shadow: none;
}

.popup :is(h2,h3,h4,.popup-header),
.popup-content :is(h2,h3,h4,.popup-header) {
    color: var(--ty-moss-deep);
    font-family: var(--ty-display);
    font-weight: 400;
    text-shadow: none;
}

.popup :is(.popup-close,.fa-close,.fa-xmark),
.popup-content :is(.popup-close,.fa-close,.fa-xmark) {
    color: var(--ty-oxblood);
    opacity: .86;
    filter: none;
    text-shadow: none;
}

.popup :is(.popup-close,.fa-close,.fa-xmark):is(:hover,:focus-visible) { opacity: 1; }

/* ===== src/windows/notifications.css ===== */
#toast-container > .toast,
.toast,
.toastr,
.toast-info,
.toast-success,
.toast-warning,
.toast-error {
    color: var(--ty-ink);
    border: 1px solid var(--ty-line);
    border-inline-start-width: 4px;
    border-radius: var(--ty-radius-m);
    background-color: var(--ty-paper-soft);
    background-image: none;
    background-repeat: no-repeat;
    box-shadow: var(--ty-shadow-soft);
    text-shadow: none;
    opacity: 1;
}

#toast-container > .toast-info,
.toast-info { border-inline-start-color: var(--ty-info); }
#toast-container > .toast-success,
.toast-success { border-inline-start-color: var(--ty-success); }
#toast-container > .toast-warning,
.toast-warning { border-inline-start-color: var(--ty-warning); }
#toast-container > .toast-error,
.toast-error { border-inline-start-color: var(--ty-error); }

#toast-container :is(.toast-title,.toast-message),
.toast :is(.toast-title,.toast-message) {
    color: var(--ty-ink);
    text-shadow: none;
}

#toast-container .toast-close-button,
.toast .toast-close-button {
    color: var(--ty-oxblood);
    opacity: .9;
    filter: none;
    text-shadow: none;
}

#toast-container .toast-progress,
.toast .toast-progress { background: var(--ty-moss); opacity: .68; }

/* ===== src/windows/mobile.css ===== */
@media (max-width: 600px) {
    body { --topBarBlockSize: 52px; --bottomFormBlockSize: 40px; }

    #top-settings-holder,
    #top-bar { width: 100dvw; }

    /* 官方负责抽屉100dvw、top和关闭；主题只处理表面。 */
    #left-nav-panel,
    #right-nav-panel,
    #user-settings-block,
    #AdvancedFormatting,
    #WorldInfo,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #rm_api_block {
        color: var(--ty-ink);
        background: var(--ty-surface-strong);
        border-radius: 0 0 var(--ty-radius-l) var(--ty-radius-l);
        box-shadow: var(--ty-shadow-soft);
        text-shadow: none;
    }

    body :is(.drawer-content,.popup,.popup-content) :is(input,textarea,select,.text_pole) {
        font-size: .96em;
    }

    #WorldInfo #world_info + span.select2.select2-container .select2-selection--multiple {
        max-height: 22dvh;
    }

    #toast-container { width: calc(100dvw - 1rem); margin: .5rem; }
    #toast-container > .toast { width: 100%; }
}

/* ===== src/fallback.css ===== */
/* 远程素材失败或被原生背景替换时，外侧退为深苔色；中央米灰纸、系统宋体和原生图标继续可用。 */
#bg1 { background-color: var(--ty-moss-deep, #29463a); }
#sheld { background-color: var(--ty-paper, #eeece4); }

body,
#chat .mes_text,
#send_textarea {
    font-family: "Source Han Serif SC", "Noto Serif SC", "Songti SC", SimSun, serif;
}

body :is(.fa,.fa-solid,.fa-regular,.fa-brands),
#top-settings-holder > .drawer > .drawer-toggle,
#leftSendForm > div,
#rightSendForm > div {
    visibility: visible;
}

#chat::before,
#top-settings-holder > .drawer > .drawer-toggle::after {
    pointer-events: none;
}
